import 'package:flutter/material.dart';void main() {  runApp(const MyApp());}class MyApp extends StatelessWidget {  const MyApp({Key? key}) : super(key: key);  @override  Widget build(BuildContext context) {    return const MaterialApp(      title: 'Simple Calculator',      home: Calculator(),    );  }}class Calculator extends StatefulWidget {  const Calculator({Key? key}) : super(key: key);  @override  State<Calculator> createState() => _CalculatorState();}class _CalculatorState extends State<Calculator> {  final _textController = TextEditingController();  double _num1 = 0;  double _num2 = 0;  String _operator = '';  String _result = '';  void _calculate() {    setState(() {      _num1 = double.parse(_textController.text);      _result = _num1.toString();    });  }  void _clear() {    setState(() {      _textController.clear();      _num1 = 0;      _num2 = 0;      _operator = '';      _result = '';    });  }  void _operatorPressed(String operator) {    setState(() {      _num1 = double.parse(_textController.text);      _operator = operator;      _textController.clear();    });  }  void _equalPressed() {    setState(() {      _num2 = double.parse(_textController.text);      switch (_operator) {        case '+':          _result = (_num1 + _num2).toString();          break;        case '-':          _result = (_num1 - _num2).toString();          break;        case '*':          _result = (_num1 * _num2).toString();          break;        case '/':          if (_num2 != 0) {            _result = (_num1 / _num2).toString();          } else {            _result = 'Error';          }          break;      }      _textController.clear();    });  }  void _numberPressed(String number) {    setState(() {      if (_operator.isEmpty) {        _textController.text += number;      } else {        _textController.text += number;      }    });  }  @override  Widget build(BuildContext context) {    return Scaffold(      appBar: AppBar(        title: const Text('Simple Calculator'),      ),      body: Padding(        padding: const EdgeInsets.all(16.0),        child: Column(          children: [            TextField(              controller: _textController,              readOnly: true,              decoration: const InputDecoration(                border: OutlineInputBorder(),              ),            ),            const SizedBox(height: 16),            Row(              mainAxisAlignment: MainAxisAlignment.spaceEvenly,              children: [                ElevatedButton(                  onPressed: () => _numberPressed('7'),                  child: const Text('7'),                ),                ElevatedButton(                  onPressed: () => _numberPressed('8'),                  child: const Text('8'),                ),                ElevatedButton(                  onPressed: () => _numberPressed('9'),                  child: const Text('9'),                ),                ElevatedButton(                  onPressed: () => _operatorPressed('/'),                  child: const Text('/'),                ),              ],            ),            const SizedBox(height: 16),            Row(              mainAxisAlignment: MainAxisAlignment.spaceEvenly,              children: [                ElevatedButton(                  onPressed: () => _numberPressed('4'),                  child: const Text('4'),                ),                ElevatedButton(                  onPressed: () => _numberPressed('5'),                  child: const Text('5'),                ),                ElevatedButton(                  onPressed: () => _numberPressed('6'),                  child: const Text('6'),                ),                ElevatedButton(                  onPressed: () => _operatorPressed('*'),                  child: const Text('*'),                ),              ],            ),            const SizedBox(height: 16),            Row(              mainAxisAlignment: MainAxisAlignment.spaceEvenly,              children: [                ElevatedButton(                  onPressed: () => _numberPressed('1'),                  child: const Text('1'),                ),                ElevatedButton(                  onPressed: () => _numberPressed('2'),                  child: const Text('2'),                ),                ElevatedButton(                  onPressed: () => _numberPressed('3'),                  child: const Text('3'),                ),                ElevatedButton(                  onPressed: () => _operatorPressed('-'),                  child: const Text('-'),                ),              ],            ),            const SizedBox(height: 16),            Row(              mainAxisAlignment: MainAxisAlignment.spaceEvenly,              children: [                ElevatedButton(                  onPressed: () => _numberPressed('0'),                  child: const Text('0'),                ),                ElevatedButton(                  onPressed: _clear,                  child: const Text('C'),                ),                ElevatedButton(                  onPressed: _equalPressed,                  child: const Text('='),                ),                ElevatedButton(                  onPressed: () => _operatorPressed('+'),                  child: const Text('+'),                ),              ],            ),            const SizedBox(height: 16),            Text(_result),          ],        ),      ),    );  }}